int licznik = 0;
int liczba = 0;
int minimum, maksimum, jasnosc;

void Znak(int iNumer) {
  // Sterowanie pinem 8 (np. kropka lub dodatkowy segment)
  digitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);

  // Sterowanie segmentami podłączonymi do PORTD (piny od D2 do D7)
  switch (iNumer) {
    case 0: PORTD = 0b11111100; break;
    case 1: PORTD = 0b01100000; break;
    case 2: PORTD = 0b11011010; break;
    case 3: PORTD = 0b11110010; break;
    case 4: PORTD = 0b01100110; break;
    case 5: PORTD = 0b10110110; break;
    case 6: PORTD = 0b10111110; break;
    case 7: PORTD = 0b11100000; break;
    case 8: PORTD = 0b11111110; break;
    case 9: PORTD = 0b11110110; break;
    default: PORTD = 0b00000000; break;
  }
}

void setup() {
  // Ustawienie pinów od D2 do D8 jako wyjścia
  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);
  minimum = analogRead(0);
  maksimum = minimum;
}

void loop() {
  // Multipleksowanie wyświetlacza dwucyfrowego (cyfra jedności)
  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);

  // Multipleksowanie wyświetlacza dwucyfrowego (cyfra dziesiątek)
  digitalWrite(10, LOW);
  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);

  // Co pewien czas odczytaj wartość z analog(0) i przeskaluj ją do zakresu 0-99
  if (licznik++ > 100) {
    jasnosc = analogRead(0);

    if (minimum > jasnosc) minimum = jasnosc;
    if (maksimum < jasnosc) maksimum = jasnosc;

    // Zabezpieczenie przed dzieleniem przez zero
    if (minimum != maksimum) {
      jasnosc = 99 * (jasnosc - minimum) / (maksimum - minimum);
    } else {
      jasnosc = 0;
    }

    liczba = jasnosc;
    licznik = 0;
  }
}
